use super::*;
use crate::{java_runtime::JavaObject::NullableObject,cn::wps::{moss::{app::KmoBookApi::KmoBookApi,engine::linktb::ExternalNameRecord::ExternalNameRecord},et::ss::formula::ptg::Ptg::Ptg},org::apache::poi::ss::SpreadsheetVersion::SpreadsheetVersion};
use kfc_kfc_alpha::kfc::{ooxfw::OxfwPackage::OxfwPackage,xpxml::writer::r#impl::MemoryXmlWriter::MemoryXmlWriter};
use serde_json::{json,Value};
use std::{rc::Rc as LocalRc,cell::RefCell as LocalCell,io::{Read,Write,Cursor},panic::{catch_unwind,AssertUnwindSafe}};
#[derive(Clone)]struct Bytes(LocalRc<LocalCell<Vec<u8>>>);impl Write for Bytes{fn write(&mut self,b:&[u8])->std::io::Result<usize>{self.0.borrow_mut().extend_from_slice(b);Ok(b.len())}fn flush(&mut self)->std::io::Result<()>{Ok(())}}
fn base64(bytes:&[u8])->String{let alphabet=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=String::new();for part in bytes.chunks(3){let v=((part[0]as u32)<<16)|((part.get(1).copied().unwrap_or(0)as u32)<<8)|part.get(2).copied().unwrap_or(0)as u32;for i in 0..4{out.push(if i>part.len(){'='}else{alphabet[((v>>(18-i*6))&63)as usize]as char});}}out}
fn thrown(e:Box<dyn std::any::Any+Send>)->String{if e.is::<crate::java_runtime::RuntimeException::RuntimeException>(){return "RuntimeException".into();}if let Some(io)=e.downcast_ref::<std::io::Error>(){if io.to_string().starts_with("ZipException:"){return "ZipException".into();}}let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");for name in ["NullPointerException","ClassCastException","IllegalStateException","RuntimeException"]{if s.starts_with(name){return name.into();}}format!("panic: {s}")}
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>json!({"result":thrown(e)})}}
fn result(f:impl FnOnce())->String{match catch_unwind(AssertUnwindSafe(f)){Ok(())=>"ok".into(),Err(e)=>thrown(e)}}
fn output(mut f:impl FnMut(&mut dyn XmlWriter))->Value{let mut m=MemoryXmlWriter::new();let mr=result(||f(&mut m));let units=m.getCodeUnits().iter().map(|v|format!("{v:04x}")).collect::<String>();let bytes=Bytes(LocalRc::new(LocalCell::new(vec![])));let mut b=BufferXmlWriter::new(Box::new(bytes.clone()));let br=result(||{f(&mut b);b.flush();});json!({"memoryResult":mr,"units":units,"bufferResult":br,"bytes":base64(&bytes.0.borrow())})}
fn object(p:&Value)->NullableObject{match p["kind"].as_str().unwrap(){"null"=>None,"number"=>Some(Rc::new(f64::from_bits(u64::from_str_radix(p["bits"].as_str().unwrap(),16).unwrap()))),"boolean"=>Some(Rc::new(p["value"].as_bool().unwrap())),"integer"=>Some(Rc::new(p["value"].as_i64().unwrap()as i32)),"error"=>Some(ErrorConstant::valueOf(p["value"].as_i64().unwrap()as i32)),_=>Some(Rc::new(p["value"].as_str().unwrap().to_string()))}}
fn block(p:&Value)->Option<Rc<ExternalBookBlock>>{
    let mode=p["mode"].as_str().unwrap_or("external");if mode=="null"{return None;}
    let mut blocks=vec![];for b in p["blocks"].as_array().unwrap(){let mut rs=vec![];for r in b["records"].as_array().unwrap(){rs.push(Some(Rc::new(CRNRecord::createCRNRecord(r["first"].as_i64().unwrap()as i32,r["last"].as_i64().unwrap()as i32,r["row"].as_i64().unwrap()as i32,Some(Rc::new(RefCell::new(r["values"].as_array().unwrap().iter().map(object).collect())))))));}blocks.push(Some(Rc::new(CRNBlock::createCRNBlock(b["sheetId"].as_i64().unwrap()as i32,Some(&rs)))));}
    let names:Vec<_>=p["names"].as_array().unwrap().iter().map(|v|v.as_str().map(str::to_string)).collect();let rec=if mode=="noRecord"{None}else if mode=="internal"{Some(Rc::new(SupBookRecord::createNullSupBook(names.len()as i16)))}else{Some(Rc::new(SupBookRecord::createExternalReferences(p["url"].as_str(),Some(Rc::new(RefCell::new(names))))))};let b=Rc::new(ExternalBookBlock::ExternalBookBlock(rec,Some(&blocks)));
    for d in p["defined"].as_array().unwrap(){let mut n=ExternalNameRecord::ExternalNameRecord();n.setText(d["text"].as_str().unwrap());n.setIx(d["ix"].as_i64().unwrap()as i16);if let Some(h)=d["ptgs"].as_str(){let bytes:Vec<_>=(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect();n.setParsedExpression(Ptg::readTokens__stream(bytes.len()as i32,&bytes,true,SpreadsheetVersion::EXCEL97));}b.addExternalName(Rc::new(n));}Some(b)
}
fn slices(book:&Rc<KmoBook>,p:&Value)->Value{let w=XlsxwExternalLinks::XlsxwExternalLinks(book.clone(),None);let b=block(p);json!({"writeSheetNames":output(|x|w.writeSheetNames(x,b.as_ref().and_then(|b|b.getExternalBookRecord()).as_deref())),"writeDefinedNames":output(|x|w.writeDefinedNames(x,b.as_deref())),"writeSheetDataSet":output(|x|w.writeSheetDataSet(x,b.as_deref()))})}
fn entries(file:&std::path::Path)->Value{let mut zip=zip::ZipArchive::new(Cursor::new(std::fs::read(file).unwrap())).unwrap();let mut out=vec![];for i in 0..zip.len(){let mut entry=zip.by_index(i).unwrap();let mut bytes=vec![];entry.read_to_end(&mut bytes).unwrap();out.push(json!({"name":entry.name(),"method":entry.compression().to_u16(),"size":entry.size(),"crc":entry.crc32(),"bytes":base64(&bytes)}));}json!(out)}
fn pipeline(book:&Rc<KmoBook>,ps:&Value,mode:usize,root:&std::path::Path)->Value{
    let bs=Rc::new(RefCell::new(ps.as_array().unwrap().iter().map(block).collect()));book.getLinkTable().borrow_mut().resetExternalBookBlocks(Some(bs.clone()));let file=root.join("zips").join(format!("native-{mode}.zip"));let mut pack=OxfwPackage::OxfwPackage(file.to_str().unwrap()).unwrap();let bp=XlsxwPackage::createBookPart(&mut pack,false,false);let w=XlsxwExternalLinks::XlsxwExternalLinks(book.clone(),Some(bp.getRelationships()));let ids=w.getExternalIds();let mut o=json!({"sameIds":Rc::ptr_eq(&ids,&w.getExternalIds()),"sameBlocks":Rc::ptr_eq(&bs,&book.getLinkTable().borrow().getAllExternalBookBlocks().unwrap())});let mut writes=vec![];let mut history=vec![];for _ in 0..if mode==1{2}else{1}{writes.push(call(||w.write()));history.push(ids.borrow().clone());}o["writes"]=json!(writes);o["history"]=json!(history);ids.borrow_mut().push("observer".into());o["idsAlias"]=json!(w.getExternalIds().borrow().last().unwrap()=="observer");o["close"]=call(||{if let Err(e)=pack.close(){std::panic::panic_any(e);}Value::Null});o["entries"]=entries(&file);o
}
#[test]
fn original_android_external_links_xml_and_package(){
    let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/external-links-write-r0b43");let j:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();crate::java_runtime::KfsZip::install();let actual=json!({"slices":input["cases"].as_array().unwrap().iter().map(|v|slices(&book,v)).collect::<Vec<_>>(),"packages":input["packages"].as_array().unwrap().iter().enumerate().map(|(i,v)|pipeline(&book,v,i,&p)).collect::<Vec<_>>()});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();
    fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}compare(&actual,&j,"root");
    let lt=book.getLinkTable();let old=lt.borrow().getAllExternalBookBlocks().unwrap();let size=old.borrow().len();old.borrow_mut().push(None);assert_eq!(lt.borrow().getAllExternalBookBlocks().unwrap().borrow().len(),size+1);lt.borrow_mut().resetExternalBookBlocks(None);assert!(lt.borrow().getAllExternalBookBlocks().is_none());lt.borrow_mut().resetExternalBookBlocks(Some(old));
}
